import os, json, re

def analyze_grid(grid):
    """
    Find key structural elements in grid:
    - h5s_row: row index with consecutive 5s of len >= 2
    - h5s_left: leftmost column of horizontal 5s
    - v5s_col: column index with consecutive 5s >= 2 ending at h5s_row
    """
    H, W = len(grid), len(grid[0])

    h5s_row = None
    h5s_left = None

    # Find row with consecutive 5s
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 5:
                # Check for consecutive 5s to the left
                left_run = c
                while left_run > 0 and grid[r][left_run-1] == 5:
                    left_run -= 1
                if c - left_run + 1 >= 2:
                    h5s_row = r
                    h5s_left = left_run
                    break
        if h5s_row is not None:
            break

    if h5s_row is None:
        return None

    # Find column with consecutive 5s ending at h5s_row
    for c in range(W):
        if grid[h5s_row][c] == 5:
            count = 0
            for r in range(h5s_row - 1, -1, -1):
                if grid[r][c] == 5:
                    count += 1
                else:
                    break
            if count >= 2:
                return {
                    'h5s_row': h5s_row,
                    'h5s_left': h5s_left,
                    'v5s_col': c,
                    'v5s_count': count
                }

    # If no vertical 5s up, check down
    for c in range(W):
        if grid[h5s_row][c] == 5:
            count = 0
            for r in range(h5s_row + 1, H):
                if grid[r][c] == 5:
                    count += 1
                else:
                    break
            if count >= 2:
                return {
                    'h5s_row': h5s_row,
                    'h5s_left': h5s_left,
                    'v5s_col': c,
                    'v5s_count': count,
                    'vertical_direction': 'down'
                }

    return None

